// WebRTC client — browser-native, no SDK, no billing
// Uses Supabase Realtime for signaling (SDP offers/answers + ICE candidates)
import { supabase } from './supabase';

let localAudioTrack = null;
let localVideoTrack = null;
let screenTrack = null;

// Per-peer state: uid -> { pc: RTCPeerConnection, audioTrack, videoTrack }
const peers = new Map();
let signalingChannel = null;
let roomId = null;
let localUid = null;
let localUserName = null;
let onRemoteTrackCb = null;
let onRemoteUserCb = null;
let onRemoteLeaveCb = null;
let isHost = false;

// ICE server config — free STUN + TURN
const ICE_SERVERS = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
  { urls: 'stun:stun2.l.google.com:19302' },
  { urls: 'turn:a.thryo.me:3478', username: 'free', credential: 'free' },
];

function createPeerConnection(peerUid) {
  const pc = new RTCPeerConnection({ iceServers: ICE_SERVERS });

  // Add local tracks if we have them
  if (localAudioTrack) {
    pc.addTrack(localAudioTrack, localAudioTrack.stream || new MediaStream([localAudioTrack]));
  }
  if (localVideoTrack) {
    pc.addTrack(localVideoTrack, localVideoTrack.stream || new MediaStream([localVideoTrack]));
  }

  // Handle remote tracks
  pc.ontrack = (event) => {
    const [remoteStream] = event.streams;
    if (onRemoteTrackCb) {
      onRemoteTrackCb(peerUid, remoteStream, event.track);
    }
  };

  // Gather ICE candidates and send via signaling
  pc.onicecandidate = (event) => {
    if (event.candidate) {
      signalingChannel.send('broadcast', {
        type: 'webrtc-signal',
        action: 'ice-candidate',
        fromUid: localUid,
        toUid: peerUid,
        candidate: event.candidate.toJSON(),
      });
    }
  };

  pc.onconnectionstatechange = () => {
    if (pc.connectionState === 'failed' || pc.connectionState === 'disconnected') {
      removePeer(peerUid);
      if (onRemoteLeaveCb) onRemoteLeaveCb(peerUid);
    }
  };

  return pc;
}

function removePeer(peerUid) {
  const peer = peers.get(peerUid);
  if (peer) {
    peer.pc.close();
    peers.delete(peerUid);
  }
}

// ==================== JOIN / LEAVE ====================

export async function joinChannel(appId, token, channelName, uid, role) {
  roomId = channelName;
  localUid = String(uid);
  localUserName = role?.userName || 'Guest';
  isHost = role?.isHost || false;
  onRemoteTrackCb = role?.onRemoteTrack;
  onRemoteUserCb = role?.onRemoteUser;
  onRemoteLeaveCb = role?.onRemoteLeave;

  // Create local media tracks
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
    localVideoTrack = stream.getVideoTracks()[0];
    localAudioTrack = stream.getAudioTracks()[0];
  } catch (err) {
    console.warn('WebRTC: camera/mic failed, audio-only:', err.message);
    try {
      const audioOnly = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
      localAudioTrack = audioOnly.getAudioTracks()[0];
    } catch (e) {
      console.warn('WebRTC: audio also failed');
    }
  }

  // Set up Supabase Realtime signaling channel
  signalingChannel = supabase.channel(`webrtc-${roomId}`, {
    config: { broadcast: { self: false } },
  });

  signalingChannel.on('broadcast', { event: 'webrtc-signal' }, async (payload) => {
    const { fromUid, toUid, action, offer, answer, candidate } = payload.payload;
    if (fromUid === localUid) return;
    if (toUid && toUid !== localUid) return; // not for us

    try {
      if (action === 'peer-joined') {
        // New peer joined — if we're host, wait for their offer
        if (onRemoteUserCb) onRemoteUserCb(fromUid, payload.payload);
      } else if (action === 'offer') {
        // Incoming offer from a peer
        await handleOffer(fromUid, offer);
      } else if (action === 'answer') {
        // Incoming answer from a peer
        await handleAnswer(fromUid, answer);
      } else if (action === 'ice-candidate') {
        // Incoming ICE candidate
        await handleIceCandidate(fromUid, candidate);
      } else if (action === 'peer-left') {
        removePeer(fromUid);
        if (onRemoteLeaveCb) onRemoteLeaveCb(fromUid);
      }
    } catch (err) {
      console.error('WebRTC signaling error:', err);
    }
  });

  await signalingChannel.subscribe();

  // Announce ourselves
  signalingChannel.send('broadcast', {
    type: 'webrtc-signal',
    action: 'peer-joined',
    fromUid: localUid,
    fromName: localUserName,
    isHost,
    hasVideo: !!localVideoTrack,
    hasAudio: !!localAudioTrack,
  });

  console.log('WebRTC: joined room', roomId, 'as uid', localUid);
  return localUid;
}

export async function leaveChannel() {
  if (signalingChannel) {
    try {
      signalingChannel.send('broadcast', {
        type: 'webrtc-signal',
        action: 'peer-left',
        fromUid: localUid,
      });
    } catch (e) {}
    await signalingChannel.unsubscribe();
    signalingChannel = null;
  }

  // Clean up local tracks
  if (localAudioTrack) { localAudioTrack.stop(); localAudioTrack = null; }
  if (localVideoTrack) { localVideoTrack.stop(); localVideoTrack = null; }
  if (screenTrack) { screenTrack.stop(); screenTrack = null; }

  // Clean up all peer connections
  for (const [uid, peer] of peers) {
    peer.pc.close();
  }
  peers.clear();

  roomId = null;
  localUid = null;
  console.log('WebRTC: left room');
}

// ==================== SIGNALING HANDLERS ====================

async function handleOffer(fromUid, offer) {
  const pc = createPeerConnection(fromUid);
  peers.set(fromUid, { pc });

  await pc.setRemoteDescription(new RTCSessionDescription(offer));
  const answer = await pc.createAnswer();
  await pc.setLocalDescription(answer);

  signalingChannel.send('broadcast', {
    type: 'webrtc-signal',
    action: 'answer',
    fromUid,
    answer: pc.localDescription.toJSON(),
  });

  if (onRemoteUserCb) onRemoteUserCb(fromUid, { uid: fromUid, name: fromUid });
}

async function handleAnswer(fromUid, answer) {
  const peer = peers.get(fromUid);
  if (!peer) return;
  await peer.pc.setRemoteDescription(new RTCSessionDescription(answer));
}

async function handleIceCandidate(fromUid, candidate) {
  const peer = peers.get(fromUid);
  if (!peer) return;
  await peer.pc.addIceCandidate(new RTCIceCandidate(candidate));
}

