// ==================== MUTE / UNMUTE ====================

export async function toggleMic() {
  if (!localAudioTrack) return false;
  const enabled = !localAudioTrack.enabled;
  localAudioTrack.enabled = enabled;
  return enabled;
}

export async function toggleCamera() {
  if (!localVideoTrack) return false;
  const enabled = !localVideoTrack.enabled;
  localVideoTrack.enabled = enabled;
  return enabled;
}

export function isMicMuted() {
  return localAudioTrack ? !localAudioTrack.enabled : true;
}

export function isCameraOff() {
  return localVideoTrack ? !localVideoTrack.enabled : true;
}

// ==================== SCREEN SHARE ====================

export async function startScreenShare(appId, token, channelName, uid) {
  void appId; void token; void channelName; void uid;
  if (!localVideoTrack) return null;
  try {
    const shareStream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
    screenTrack = shareStream.getVideoTracks()[0];

    // Replace video track in all peer connections
    const videoTrack = screenTrack;
    for (const [, peer] of peers) {
      const sender = peer.pc.getSenders().find(s => s.track?.kind === 'video');
      if (sender) {
        await sender.replaceTrack(videoTrack);
      } else {
        peer.pc.addTrack(videoTrack, new MediaStream([videoTrack]));
      }
    }

    screenTrack.onended = () => {
      stopScreenShare();
    };

    return screenTrack;
  } catch (err) {
    console.warn('Screen share failed:', err.message);
    return null;
  }
}

export async function stopScreenShare() {
  if (screenTrack) {
    screenTrack.stop();
    screenTrack = null;
  }
  // Restore camera track
  if (localVideoTrack) {
    for (const [, peer] of peers) {
      const sender = peer.pc.getSenders().find(s => s.track?.kind === 'video');
      if (sender) {
        await sender.replaceTrack(localVideoTrack);
      }
    }
  }
}

export function isScreenSharing() {
  return screenTrack !== null;
}

// ==================== GETTERS ====================

export function getLocalVideoTrack() {
  return localVideoTrack;
}

export function getLocalStream() {
  const tracks = [];
  if (localVideoTrack) tracks.push(localVideoTrack);
  if (localAudioTrack) tracks.push(localAudioTrack);
  return new MediaStream(tracks);
}

export function getScreenTrack() {
  return screenTrack;
}

export function getPeers() {
  return peers;
}

// ==================== CLEANUP ====================

export async function destroyAgoraClient() {
  await leaveChannel();
}