// Signaling client — tries WebSocket first, falls back to local-only
// App.js uses this for chat messaging (text only, Agora handles video/audio)

let activeSocket = null;

export function joinSignalingRoom(roomId, userId, userName, role, callbacks = {}) {
  // Close previous connection
  if (activeSocket) {
    try { activeSocket.close(); } catch (e) {}
    activeSocket = null;
  }

  let connected = false;

  // Try WebSocket to local signaling server
  const tryConnect = () => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const ws = new WebSocket(`${protocol}//${host}:3001`);

    ws.onopen = () => {
      connected = true;
      ws.send(JSON.stringify({ type: 'join', roomId, userId, userName, role }));
    };

    ws.onmessage = (event) => {
      let data;
      try { data = JSON.parse(event.data); } catch (e) { return; }
      // App.js expects event.data as a JSON string
      if (callbacks.onmessage) {
        callbacks.onmessage({ data: JSON.stringify(data) });
      }
    };

    ws.onclose = () => {
      connected = false;
      if (callbacks.onclose) callbacks.onclose();
    };

    ws.onerror = () => {};
    activeSocket = ws;
  };

  tryConnect();

  // Return WebSocket-like interface matching what App.js uses
  return {
    send(msg) {
      if (activeSocket && activeSocket.readyState === WebSocket.OPEN) {
        activeSocket.send(typeof msg === 'string' ? msg : JSON.stringify(msg));
      }
      // If no connection, message is silently dropped (local-only mode)
    },
    close() {
      if (activeSocket && activeSocket.readyState === WebSocket.OPEN) {
        activeSocket.send(JSON.stringify({ type: 'peer-left' }));
        activeSocket.close();
      }
      activeSocket = null;
    },
    get readyState() {
      return activeSocket ? activeSocket.readyState : 3; // CLOSED
    }
  };
}
